{"path": "/tmp/sv-0be792b56476429a9bbb0a5249dd436b/Components/Pages/Catalog.razor", "file_text": "@page "/catalog"
@using sv_0be792b56476429a9bbb0a5249dd436b.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

<div class="catalog-layout">
    <!-- Left Sidebar: Filters -->
    <aside class="catalog-sidebar">
        <h4>Filters</h4>

        @if (categories is not null)
        {
            <div class="filter-section">
                <h5>Categories</h5>
                @foreach (var category in categories)
                {
                    <label class="filter-checkbox">
                        <input type="checkbox"
                               checked="@selectedCategories.Contains(category)"
                               @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                        @category
                    </label>
                }
            </div>
        }

        <div class="filter-section">
            <h5>Price Range</h5>
            <div class="price-inputs">
                <input type="number" placeholder="Min" step="0.01" min="0"
                       @bind="minPrice" @bind:event="oninput" class="price-input" />
                <span>&ndash;</span>
                <input type="number" placeholder="Max" step="0.01" min="0"
                       @bind="maxPrice" @bind:event="oninput" class="price-input" />
            </div>
        </div>

        <div class="filter-section">
            <label class="filter-checkbox">
                <input type="checkbox" @bind="inStockOnly" />
                In Stock Only
            </label>
        </div>

        <div class="filter-actions">
            <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    <!-- Main Content Area -->
    <section class="catalog-main">
        @if (errorMessage is not null)
        {
            <div class="alert alert-danger">
                <strong>Error:</strong> @errorMessage
                <button class="btn btn-sm btn-outline-danger ms-2" @onclick="RetryLoad">Retry</button>
            </div>
        }
        else if (isLoading)
        {
            <div class="loading-indicator">
                <p>Loading products...</p>
            </div>
        }
        else if (searchResult is not null)
        {
            <!-- Toolbar -->
            <div class="catalog-toolbar">
                <div class="sort-control">
                    <label for="sort-select">Sort by:</label>
                    <select id="sort-select" @bind="sortBy" @bind:after="OnSortChanged">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A-Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                <span class="results-summary">
                    @if (searchResult.TotalCount > 0)
                    {
                        var first = (searchResult.Page - 1) * searchResult.PageSize + 1;
                        var last = Math.Min(searchResult.Page * searchResult.PageSize, searchResult.TotalCount);
                        @($"Showing {first}–{last} of {searchResult.TotalCount} products")
                    }
                    else
                    {
                        @("No products found")
                    }
                </span>
            </div>

            @if (searchResult.Items.Count == 0)
            {
                <div class="empty-state">
                    <p>No products match your filters. Try adjusting your criteria.</p>
                </div>
            }
            else
            {
                <!-- Product Grid -->
                <div class="product-grid">
                    @foreach (var product in searchResult.Items)
                    {
                        <div class="product-card" @onclick="() => OnProductSelected(product)">
                            <div class="product-image" title="@product.Name">
                                <span>@product.Name</span>
                            </div>
                            <div class="product-info">
                                <h5 class="product-name">@product.Name</h5>
                                <p class="product-price">@product.Price.ToString("C")</p>
                                <p class="product-rating">@GetStarRating(product.Rating)</p>
                                @if (!product.InStock)
                                {
                                    <span class="badge-out-of-stock">Out of Stock</span>
                                }
                                <button class="btn btn-sm btn-primary add-to-cart-btn"
                                        disabled="@(!product.InStock)"
                                        @onclick="() => AddToCart(product)"
                                        @onclick:stopPropagation="true">
                                    Add to Cart
                                </button>
                            </div>
                        </div>
                    }
                </div>

                <!-- Pagination -->
                @{
                    var totalPages = (int)Math.Ceiling((double)searchResult.TotalCount / searchResult.PageSize);
                }
                @if (totalPages > 1)
                {
                    <nav class="pagination-controls">
                        <button class="btn btn-outline-secondary"
                                disabled="@(currentPage <= 1)"
                                @onclick="() => GoToPage(currentPage - 1)">
                            Previous
                        </button>

                        @for (var i = 1; i <= totalPages; i++)
                        {
                            var pageNum = i;
                            <button class="btn @(pageNum == currentPage ? "btn-primary" : "btn-outline-secondary")"
                                    @onclick="() => GoToPage(pageNum)">
                                @pageNum
                            </button>
                        }

                        <button class="btn btn-outline-secondary"
                                disabled="@(currentPage >= totalPages)"
                                @onclick="() => GoToPage(currentPage + 1)">
                            Next
                        </button>
                    </nav>
                }
            }
        }
    </section>
</div>

